// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import {
  CameraIcon,
  InfoIcon,
  MaximizeIcon,
  PlayIcon,
  PlaySquareIcon,
  RepeatIcon,
  SettingsIcon,
  SkipForwardIcon,
  Volume2Icon,
} from 'lucide-react'
import type { ReactNode } from 'react'

import {
  Bar,
  BrowserChrome,
  DemoStage,
  DockHeader,
  Toggle,
  type Build,
} from '@/app/demos/stage'

import {
  CAPTIONS,
  FOCUS_ACTIVE,
  PICKED_THEME,
  PLAYER_ROWS,
  PRESETS,
  RELATED,
  SPONSOR,
  THEMES,
} from './script'

const build: Build = ({ tl, q, qa, step, final, move, click, count, wait, cursorOut }) => {
  const head = { p: 0.08 }
  const paint = () => {
    const percent = `${head.p * 100}%`
    q('played').style.width = percent
    q('head').style.left = percent
  }
  const play = (to: number, duration: number, at?: number | string) =>
    tl.to(head, { p: to, duration, ease: 'none', onUpdate: paint }, at)
  let active = 0
  const bump = (to: number) => {
    count('active', to, { from: active, at: '<', duration: 0.4 })
    active = to
  }
  const toggle = (d: string) => {
    move(d)
    click(d)
    tl.to(q(`${d}-fill`), { opacity: 1, duration: 0.2 }, '<')
    tl.to(q(`${d}-knob`), { x: 12, duration: 0.25, ease: 'back.out(2)' }, '<')
  }

  const start = tl.duration()
  step(0)
  move('preset-1', { at: 0.3 })
  click('preset-1')
  tl.to(
    q('related'),
    { width: 0, opacity: 0, marginLeft: -8, duration: 0.6, ease: 'power3.inOut' },
    '<',
  )
  tl.to(
    [q('comments'), q('shorts')],
    { opacity: 0, height: 0, marginTop: 0, duration: 0.5, ease: 'power2.inOut' },
    '<',
  )
  tl.to(q('next-btn'), { opacity: 0, width: 0, duration: 0.3 }, '<')
  bump(FOCUS_ACTIVE)

  step(1, '+=0.5')
  PLAYER_ROWS.forEach((_, index) => {
    toggle(`player-${index}`)
    tl.fromTo(
      q(`player-btn-${index}`),
      { opacity: 0, scale: 0.4 },
      { opacity: 1, scale: 1, duration: 0.3, ease: 'back.out(3)' },
      '<',
    )
    bump(FOCUS_ACTIVE + index + 1)
  })

  step(2, '+=0.5')
  move(`theme-${PICKED_THEME}`)
  click(`theme-${PICKED_THEME}`)
  tl.to(q(`theme-${PICKED_THEME}`), { boxShadow: '0 0 0 2px #f5f5f7', duration: 0.2 }, '<')
  tl.to(q('theme-0'), { boxShadow: '0 0 0 0px #f5f5f7', duration: 0.2 }, '<')
  tl.to(
    q('played'),
    {
      backgroundColor: THEMES[PICKED_THEME].bar,
      boxShadow: `0 0 8px ${THEMES[PICKED_THEME].bar}`,
      duration: 0.4,
    },
    '<',
  )
  tl.to(q('head'), { backgroundColor: THEMES[PICKED_THEME].bar, duration: 0.4 }, '<')
  bump(FOCUS_ACTIVE + PLAYER_ROWS.length + 1)
  play(SPONSOR.start - 0.02, tl.duration() - start, start)

  step(3, '+=0.4')
  play(SPONSOR.start + 0.03, 1.1)
  tl.fromTo(q('frame-sponsor'), { opacity: 0 }, { opacity: 1, duration: 0.3 }, '>-0.6')
  toggle('sponsor')
  bump(FOCUS_ACTIVE + PLAYER_ROWS.length + 2)
  tl.to(head, { p: SPONSOR.end, duration: 0.05, ease: 'none', onUpdate: paint }, '+=0.25')
  tl.to(q('frame-sponsor'), { opacity: 0, duration: 0.2 }, '<')
  tl.fromTo(
    q('head'),
    { scale: 1.8 },
    { scale: 1, duration: 0.4, ease: 'back.out(3)', immediateRender: false },
    '<',
  )
  play(SPONSOR.end + 0.06, 1.4)
  cursorOut('<0.4')
  final()
  wait(0.8)

  tl.set(qa('player-btn'), { opacity: 0 }, 0)
}

function Section({ title, children }: { title: string; children: ReactNode }) {
  return (
    <div>
      <p className="mb-1 text-[9.5px] font-semibold uppercase tracking-[0.12em] text-muted">
        {title}
      </p>
      {children}
    </div>
  )
}

